      let m2 = mark(p)
      if (p.tok.kind in {tkSemiColon}):
        expect p, tkSemiColon
      else:
        checkInd p, {icEq}
      discardUnused m2
      pComplexOrSimpleStmt p
    if ((p.tok.kind in Tk7)) and indClass(p) == icGt:
      error p, "invalid indentation in module"
    discardUnused m1
  wrap p, m0, "stmts"
  discardUnused m0

