              discardUnused m34
            discardUnused m32
          pOptPar p
          expect p, tkParRi
          wrap p, m0, "par"
        elif (p.tok.kind in {tkColon}):
          expect p, tkColon
          pExpr p
          if (p.tok.kind in {tkComma}):
            expect p, tkComma
            let m35 = mark(p)
            pExprColonEqExpr p
