proc pPrimarySuffix*(p: var Parser; anchor: Mark; mode: PrimaryMode) =
  let m0 = mark(p)
  if ((p.tok.kind in {tkBracketLe, tkCurlyLe, tkParLe})) and noSpaceBefore(p):
    if (p.tok.kind in {tkParLe}):
      expect p, tkParLe
      while (p.tok.kind in Tk1):
        let m39 = mark(p)
        pExprColonEqExpr p
        if (p.tok.kind in {tkComma}):
          pComma p
        discardUnused m39
      expect p, tkParRi
      wrap p, anchor, "call"
    elif (p.tok.kind in {tkBracketLe}):
      expect p, tkBracketLe
      pOptInd p
      pExprColonEqExprList p
      pOptPar p
      expect p, tkBracketRi
      wrap p, anchor, "at"
    elif (p.tok.kind in {tkCurlyLe}):
      expect p, tkCurlyLe
      pOptInd p
      pExprColonEqExprList p
      pOptPar p
      expect p, tkCurlyRi
      wrap p, anchor, "curlyat"
    else:
      error p, "expected primarySuffix"
  elif (p.tok.kind in {tkDot}):
    expect p, tkDot
    pOptInd p
    pSymbolOrKeyword p
    if (p.tok.kind in {tkBracketLeColon}):
      expect p, tkBracketLeColon
      pExprList p
      expect p, tkBracketRi
      if (p.tok.kind in {tkParLe}):
        expect p, tkParLe
        pExprColonEqExpr p
        expect p, tkParRi
    wrap p, anchor, "dot"
    if (p.tok.kind in {tkGStrLit, tkGTripleStrLit}):
      pGeneralizedLit p
  elif (((p.tok.kind == tkOpr and isDotLike(p.tok)))) and dotLikeOps(p):
    emitLeaf p            # DOTLIKEOP
    pOptInd p
    pSymbolOrKeyword p
    wrap p, anchor, "dot"
    if (p.tok.kind in {tkGStrLit, tkGTripleStrLit}):
      pGeneralizedLit p
  elif ((p.tok.kind in Tk1)) and commandStart(p) and commandAllowed(p, mode):
    pCommandParam(p, mode)
    wrap p, anchor, "cmd"
  else:
    error p, "expected primarySuffix"
  discardUnused m0

proc pPragma*(p: var Parser) =
